#!/usr/bin/env bash
set -Eeuo pipefail;cd "$(dirname "$0")";archive=${1:-};[ -f "$archive" ]||{ echo 'Usage: ./restore.sh path/to/backup.tar.gz';exit 2; };read -r -p 'This replaces database and stored files. Type RESTORE: ' ok;[ "$ok" = RESTORE ]||exit 1;docker compose stop atlas;tmp=$(mktemp -d);trap 'rm -rf "$tmp"' EXIT;tar -xzf "$archive" -C "$tmp";[ -s "$tmp/atlas.sqlite" ]||{ echo 'Invalid backup';exit 3; };docker run --rm -v atlas_forex_replay_data:/data -v "$tmp:/restore:ro" alpine:3.21 sh -c 'cp /restore/atlas.sqlite /data/atlas.sqlite; for d in market screenshots; do [ ! -d /restore/$d ] || cp -a /restore/$d /data/; done';docker compose up -d atlas;echo 'Restore complete.'
